"use client"
import React, {  useState  } from 'react'
import DashboradSup from "../dashboradComponents/DashboradSup"
import { Search } from 'react-bootstrap-icons'
import Link from 'next/link'
import { subType } from '../../assets/assets'
import { useThemeContext } from '@/app/assets/contexts'

export default function DashboardSubs({plans}:{plans:subType[]}) {
  const [searchValue , setSearchValue] = useState<string>("")
  const { theme } = useThemeContext()




 
  
  
  const plansMap = plans.map((sub)=>{
      return(
        <DashboradSup key={sub.id} sub={sub} />
      )
    })
    
  const filteredPlans = plans.filter(plan => plan.name.toLowerCase().includes(searchValue.toLowerCase()))
    const filteredPlansMap = filteredPlans.map((sub) => {
          return (
              <DashboradSup key={sub.id} sub={sub} />
          )
    })

  const handleChange = (e:React.ChangeEvent<HTMLInputElement>)=>{
    const value = e.target.value
    setSearchValue(value)
  }
  return (
    <article className={`p-3  ${theme==="light"?"bg-gray-200":"bg-gray-800"} rounded-2xl mb-2.5 bg-gray-200 border-t-4 border-l-4 border-blue-600`}>
        <div className="flex justify-between  items-start md:items-center flex-col md:flex-row">
          <h3 className='mb-2.5 text-2xl capitalize text-blue-600'> all subs</h3>
            <div className="relative mb-5 w-full md:w-1/2 ">
              <input type="text"
                placeholder='search sub'
                value={searchValue} 
                onChange={handleChange}
                className=' focus:bg-blue-400 w-full p-3 border border-blue-600 rounded-2xl' 
                />
              <Search className={` absolute top-1/2 left-2.5 -translate-y-1/2  `} />
            </div>
        </div>
        <div>
        {plans.length === 0 ?
          <h3 className='text-center text-3xl text-blue'> جاري التحميل </h3> :
          searchValue!=="" ? filteredPlansMap : plansMap
        }
        </div>
        <Link   className='text-center mt-2.5 p-2 capitalize bg-blue-600 inline-block w-full rounded-2xl hover:bg-blue-800' href={"/addsub"}> add new sub </Link>
    </article>
  )
}
